// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    address owner = address(0); // _contractOwner defaults to address(0)

    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address logger, bool status) public {
        vm.assume(logger != address(0));
        vm.prank(owner);
        c.setApprovedLogger(logger, status);
        assertTrue(c.approvedToLog(logger) == status);
    }
}
